/**
 * JTS based helpers for the {@code geox:} functions: parsing and writing {@code geo:wktLiteral}s with an optional
 * {@code <crs>} prefix, the small set of supported coordinate reference systems and spherical measurements.
 */
@InternalUseOnly
public final class GeoSupport {

	private GeoSupport() {
	}

	public static final String CRS84 = GEO.DEFAULT_SRID;
	public static final String EPSG_PREFIX = "http://www.opengis.net/def/crs/EPSG/0/";
	public static final String EPSG_4326 = EPSG_PREFIX + "4326";
	public static final String EPSG_3857 = EPSG_PREFIX + "3857";

	/** Mean Earth radius in metres (IUGG). */
	public static final double EARTH_RADIUS_M = 6_371_008.8;

	private static final GeometryFactory FACTORY = new GeometryFactory(new PrecisionModel(), 0);

	private static final ThreadLocal<WKTReader> READER = ThreadLocal.withInitial(() -> new WKTReader(FACTORY));

	/** A parsed WKT literal: the geometry plus the CRS IRI (the default CRS84 when the literal has no prefix). */
	public record Geo(Geometry geometry, String crs) {

		public boolean isGeographic() {
			return CRS84.equals(crs) || EPSG_4326.equals(crs);
		}

		/** Longitude of a coordinate honouring the axis order of the CRS. */
		double lon(Coordinate c) {
			return EPSG_4326.equals(crs) ? c.y : c.x;
		}

		double lat(Coordinate c) {
			return EPSG_4326.equals(crs) ? c.x : c.y;
		}
	}

	public static GeometryFactory factory() {
		return FACTORY;
	}

	public static Geo parse(Function function, Value arg) {
		if (!(arg instanceof Literal literal) || literal.getCoreDatatype() != CoreDatatype.GEO.WKT_LITERAL) {
			throw new ValueExprEvaluationException(
					"Invalid argument for " + function.getURI() + ": expected a geo:wktLiteral but got " + arg);
		}
		String wkt = literal.getLabel().trim();
		String crs = CRS84;
		if (wkt.startsWith("<")) {
			int end = wkt.indexOf('>');
			if (end < 0) {
				throw new ValueExprEvaluationException("Invalid WKT literal for " + function.getURI() + ": " + arg);
			}
			crs = wkt.substring(1, end).trim();
			wkt = wkt.substring(end + 1).trim();
		}
		try {
			return new Geo(READER.get().read(wkt), crs);
		} catch (ParseException | IllegalArgumentException e) {
			throw new ValueExprEvaluationException("Invalid WKT literal for " + function.getURI() + ": " + arg, e);
		}
	}

	public static Literal toLiteral(ValueFactory vf, Geometry geometry, String crs) {
		String wkt = new WKTWriter().write(geometry);
		if (!CRS84.equals(crs)) {
			wkt = "<" + crs + "> " + wkt;
		}
		return vf.createLiteral(wkt, CoreDatatype.GEO.WKT_LITERAL);
	}

	/** Resolves a CRS argument: an EPSG/OGC IRI, an integer EPSG code or a string such as "EPSG:3857". */
	public static String crs(Function function, Value arg) {
		if (arg instanceof IRI iri) {
			return iri.stringValue();
		}
		if (arg instanceof Literal literal) {
			CoreDatatype datatype = literal.getCoreDatatype();
			if (datatype.isXSDDatatype() && ((CoreDatatype.XSD) datatype).isIntegerDatatype()) {
				return EPSG_PREFIX + literal.integerValue();
			}
			String label = literal.getLabel().trim();
			if (label.regionMatches(true, 0, "EPSG:", 0, 5)) {
				return EPSG_PREFIX + new BigInteger(label.substring(5).trim());
			}
			if (label.equalsIgnoreCase("CRS84") || label.equalsIgnoreCase("OGC:CRS84")) {
				return CRS84;
			}
			if (label.startsWith("http")) {
				return label;
			}
		}
		throw new ValueExprEvaluationException("Invalid CRS argument for " + function.getURI() + ": " + arg);
	}

	/**
	 * Transforms a geometry between CRS84, EPSG:4326 (latitude/longitude axis order) and EPSG:3857 (Web Mercator).
	 */
	public static Geometry transform(Function function, Geo source, String targetCrs) {
		if (source.crs().equals(targetCrs)) {
			return source.geometry();
		}
		boolean sourceSupported = source.isGeographic() || EPSG_3857.equals(source.crs());
		boolean targetSupported = CRS84.equals(targetCrs) || EPSG_4326.equals(targetCrs)
				|| EPSG_3857.equals(targetCrs);
		if (!sourceSupported || !targetSupported) {
			throw new ValueExprEvaluationException(function.getURI() + " only supports transformations between "
					+ "CRS84, EPSG:4326 and EPSG:3857; got " + source.crs() + " -> " + targetCrs);
		}
		Geometry copy = source.geometry().copy();
		String sourceCrs = source.crs();
		copy.apply((CoordinateFilter) c -> {
			double lon;
			double lat;
			if (EPSG_3857.equals(sourceCrs)) {
				lon = Math.toDegrees(c.x / EARTH_RADIUS_WGS84);
				lat = Math.toDegrees(2 * Math.atan(Math.exp(c.y / EARTH_RADIUS_WGS84)) - Math.PI / 2);
			} else if (EPSG_4326.equals(sourceCrs)) {
				lat = c.x;
				lon = c.y;
			} else {
				lon = c.x;
				lat = c.y;
			}
			if (EPSG_3857.equals(targetCrs)) {
				if (Math.abs(lat) >= 90) {
					throw new ValueExprEvaluationException("Latitude " + lat + " cannot be projected to EPSG:3857");
				}
				c.x = Math.toRadians(lon) * EARTH_RADIUS_WGS84;
				c.y = Math.log(Math.tan(Math.PI / 4 + Math.toRadians(lat) / 2)) * EARTH_RADIUS_WGS84;
			} else if (EPSG_4326.equals(targetCrs)) {
				c.x = lat;
				c.y = lon;
			} else {
				c.x = lon;
				c.y = lat;
			}
		});
		copy.geometryChanged();
		return copy;
	}

	/** WGS84 semi-major axis used by the spherical Web Mercator projection. */
	public static final double EARTH_RADIUS_WGS84 = 6_378_137.0;

	/** Great-circle length of a geometry in metres (geographic CRS). */
	public static double sphericalLength(Geo geo) {
		double total = 0;
		Geometry geometry = geo.geometry();
		for (int i = 0; i < geometry.getNumGeometries(); i++) {
			Geometry part = geometry.getGeometryN(i);
			if (part instanceof Polygon polygon) {
				total += ringLength(geo, polygon.getExteriorRing().getCoordinates());
				for (int r = 0; r < polygon.getNumInteriorRing(); r++) {
					total += ringLength(geo, polygon.getInteriorRingN(r).getCoordinates());
				}
			} else if (part instanceof LineString line) {
				total += ringLength(geo, line.getCoordinates());
			}
		}
		return total;
	}

	private static double ringLength(Geo geo, Coordinate[] coordinates) {
		double total = 0;
		for (int i = 1; i < coordinates.length; i++) {
			total += haversine(geo.lat(coordinates[i - 1]), geo.lon(coordinates[i - 1]), geo.lat(coordinates[i]),
					geo.lon(coordinates[i]));
		}
		return total;
	}

	public static double haversine(double lat1, double lon1, double lat2, double lon2) {
		double dLat = Math.toRadians(lat2 - lat1);
		double dLon = Math.toRadians(lon2 - lon1);
		double a = Math.sin(dLat / 2) * Math.sin(dLat / 2)
				+ Math.cos(Math.toRadians(lat1)) * Math.cos(Math.toRadians(lat2)) * Math.sin(dLon / 2)
						* Math.sin(dLon / 2);
		return 2 * EARTH_RADIUS_M * Math.asin(Math.min(1.0, Math.sqrt(a)));
	}

	/** Area of a geometry on the sphere in square metres (geographic CRS), holes subtracted. */
	public static double sphericalArea(Geo geo) {
		double total = 0;
		Geometry geometry = geo.geometry();
		for (int i = 0; i < geometry.getNumGeometries(); i++) {
			if (geometry.getGeometryN(i) instanceof Polygon polygon) {
				total += Math.abs(ringArea(geo, polygon.getExteriorRing().getCoordinates()));
				for (int r = 0; r < polygon.getNumInteriorRing(); r++) {
					total -= Math.abs(ringArea(geo, polygon.getInteriorRingN(r).getCoordinates()));
				}
			}
		}
		return Math.max(0, total);
	}

	/** Signed spherical ring area (Chamberlain &amp; Duquette). */
	private static double ringArea(Geo geo, Coordinate[] coordinates) {
		int n = coordinates.length;
		if (n < 3) {
			return 0;
		}
		double sum = 0;
		for (int i = 0; i < n; i++) {
			Coordinate lower = coordinates[i];
			Coordinate middle = coordinates[(i + 1) % n];
			Coordinate upper = coordinates[(i + 2) % n];
			sum += (Math.toRadians(geo.lon(upper)) - Math.toRadians(geo.lon(lower)))
					* Math.sin(Math.toRadians(geo.lat(middle)));
		}
		return sum * EARTH_RADIUS_M * EARTH_RADIUS_M / 2;
	}

	/** Resolves an optional unit argument: the GeoSPARQL metre unit selects spherical measurement. */
	public static boolean metres(Function function, Value unit) {
		if (unit instanceof IRI iri) {
			if (GEOF.UOM_METRE.equals(iri)) {
				return true;
			}
			if (GEOF.UOM_DEGREE.equals(iri) || GEOF.UOM_UNITY.equals(iri)) {
				return false;
			}
		}
		throw new ValueExprEvaluationException("Unsupported unit for " + function.getURI() + ": " + unit
				+ " (expected uom:metre or uom:degree)");
	}
}
